// Portal half of the creature specs a build returns (Cyrus R3). The build service validated them with its generated
// JS copy of ./spec.ts; the portal never trusts that: it re-validates, compiles (.bbmodel + skin), runs the skin
// quality bar and identifies each RigSpec by the sha256 of its canonical JSON as WRITTEN (template form stays small).
import { canonicalJson, sha256Hex } from "../assets/textures";
import { compileCreature, type CompiledCreature } from "./compile";
import { skinQuality, type SkinQuality } from "./quality";
import type { Raster } from "../textures/render";
import { checkRigSpec, MAX_CREATURES, MAX_RIG_SPEC_BYTES, modelKey, NAME_RE, type RigSpec } from "./spec";

export const RIG_SPEC_MIME = "application/vnd.nxeon.rig-spec+json";

export type CheckedCreature =
  | { ok: true; name: string; key: string; input: unknown; spec: RigSpec; specSha256: string; canonical: string; compiled: CompiledCreature; quality: SkinQuality; warnings: string[] }
  | { ok: false; name: string; reason: string };

export function checkReturnedCreature(c: { name?: unknown; spec?: unknown }, namespace: string, opts: { paint?: (base: Raster) => Raster } = {}): CheckedCreature {
  const name = typeof c.name === "string" && NAME_RE.test(c.name) ? c.name : "?";
  const canonical = canonicalJson(c.spec ?? null);
  if (Buffer.byteLength(canonical) > MAX_RIG_SPEC_BYTES) return { ok: false, name, reason: `the creature spec is larger than ${MAX_RIG_SPEC_BYTES / 1024} KB` };
  const chk = checkRigSpec(c.spec, { namespace });
  if (!chk.ok) return { ok: false, name, reason: chk.error };
  if (chk.spec.name !== name) return { ok: false, name, reason: `spec name ${chk.spec.name} does not match ${name}` };
  const r = compileCreature(chk.spec, namespace, opts);
  if (!r.ok) return { ok: false, name, reason: r.error };
  const quality = skinQuality(r.creature.raster, r.creature.layout);
  if (quality.verdict === "fail") return { ok: false, name, reason: `the skin failed Nxeon's skin checks (${quality.checks.filter((q) => q.verdict === "fail").map((q) => q.id).join(", ")})` };
  return { ok: true, name, key: modelKey(namespace, name), input: c.spec, spec: chk.spec, specSha256: sha256Hex(canonical), canonical, compiled: r.creature, quality, warnings: chk.warnings };
}

/** Re-check every returned creature (at most MAX_CREATURES, first wins on a duplicate name). */
export function checkReturnedCreatures(list: { name?: unknown; spec?: unknown }[] | undefined, namespace: string): { ok: Extract<CheckedCreature, { ok: true }>[]; dropped: { name: string; reason: string }[] } {
  const ok: Extract<CheckedCreature, { ok: true }>[] = [];
  const dropped: { name: string; reason: string }[] = [];
  for (const c of (list ?? []).slice(0, MAX_CREATURES)) {
    const r = checkReturnedCreature(c, namespace);
    if (!r.ok) { dropped.push({ name: r.name, reason: r.reason }); continue; }
    if (ok.some((x) => x.name === r.name)) continue;
    ok.push(r);
  }
  return { ok, dropped };
}
// Generated files of the Cyrus creature pipeline (R3), all committed (neither the portal nor the build service needs
// esbuild at runtime); test/cyrus-creature.test.ts rebuilds them in memory and fails when one is stale:
//   services/modbuilder/creature-spec.js        the build service's RigSpec validator (bundled from spec.ts + zod)
//   lib/cyrus/creature/rigspec.v1.schema.json   the portable JSON Schema contract (z.toJSONSchema of RigSpecV1Schema)
//   services/modbuilder/creature-example.json   the example the CREATURE section shows (= the golden banshee fixture)
//   npx tsx scripts/cyrus/build-creature-artifacts.ts [--check]
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { rigSpecJsonSchema } from "../../lib/cyrus/creature/spec";

const ROOT = path.join(__dirname, "../..");
const HEADER = `"use strict";\n// GENERATED by scripts/cyrus/build-creature-artifacts.ts from lib/cyrus/creature/spec.ts + templates.ts (+ zod). Do not edit. The build service's RigSpec validator.`;

export async function creatureArtifacts(): Promise<Record<string, string>> {
  const esbuild = await import("esbuild");
  const r = await esbuild.build({ entryPoints: [path.join(ROOT, "lib/cyrus/creature/spec-entry.ts")], bundle: true, platform: "node", format: "cjs", target: "node20", write: false, minify: true, legalComments: "none", banner: { js: HEADER } });
  const example = JSON.stringify(JSON.parse(readFileSync(path.join(ROOT, "test/fixtures/cyrus-creatures/banshee.json"), "utf8")), null, 1) + "\n";
  return {
    "services/modbuilder/creature-spec.js": r.outputFiles[0].text,
    "lib/cyrus/creature/rigspec.v1.schema.json": JSON.stringify(rigSpecJsonSchema(), null, 2) + "\n",
    "services/modbuilder/creature-example.json": example,
  };
}

if (require.main === module) {
  creatureArtifacts().then((files) => {
    let stale = 0;
    for (const [rel, text] of Object.entries(files)) {
      const abs = path.join(ROOT, rel);
      if (process.argv.includes("--check")) {
        let cur = ""; try { cur = readFileSync(abs, "utf8"); } catch { /* missing */ }
        if (cur !== text) { stale++; console.error(`stale: ${rel}`); }
      } else { writeFileSync(abs, text); console.log(`wrote ${rel} (${Buffer.byteLength(text)} bytes)`); }
    }
    if (stale) { console.error("run: npx tsx scripts/cyrus/build-creature-artifacts.ts"); process.exit(1); }
  }).catch((e) => { console.error(e); process.exit(1); });
}

