// Creature delivery to ONE server (Cyrus R3, worker side, runs after the Mods engine installed/updated/removed a Cyrus
// mod's jar; same guest connection). For a build with creatures:
//   1. ensure the Nxeon-managed BetterModel (lib/cyrus/managed, ref-counted by project; pinned per family: 2.2.0 for
//      1.21.x (Java 21, bundle mc-coverage), 3.5.0 for 26.x (Java 25)),
//   2. write Nxeon's managed BetterModel config (plugins/BetterModel/config.yml) when it is missing or still Nxeon's,
//   3. write each creature's compiled model to plugins/BetterModel/models/<namespace>_<name>.bbmodel (re-compiled from
//      the stored RigSpec + the stored Model Studio paint when there is one, refused when the bytes differ from what
//      the build recorded) and remove this project's models
//      that the new version no longer has,
//   4. the server needs a restart (or `/bettermodel reload`): BetterModel then builds its pack, and the hand-off
//      (./handoff.ts) publishes it and points the Pack Loader at it.
// OFF unless BOTH CYRUS_MANAGED_PLUGINS_REAL=1 (the existing managed-plugin switch) and CYRUS_CREATURES=1: otherwise
// nothing here reads the database or touches a server.
import { readFileSync } from "node:fs";
import path from "node:path";
import type { HostGuestFs as GuestFs } from "../host/types";
import { MANAGED_REAL_FLAG } from "../managed/installer";
import { loadCatalog, pinFor } from "../managed/catalog";
import { ensureManagedPlugin, releaseManagedPlugin, type ManagedDeps } from "../managed/service";
import { MC_BASE } from "../packhost/deliver";
import { compileCreature } from "./compile";
import { checkRigSpec, modelKey } from "./spec";
import { checkCreaturePaint, paintSkin, type CreaturePaint } from "./paint";

export const BETTERMODEL_KEY = "bettermodel";
export const CREATURES_FLAG = "CYRUS_CREATURES";
export const MODELS_DIR = "plugins/BetterModel/models";
export const CONFIG_PATH = "plugins/BetterModel/config.yml";
export const CONFIG_MARKER = "# Nxeon-managed BetterModel";

/** What ModBuild.result.assets.creatures stores per creature (lib/cyrus/assets/sync.ts). */
export type StoredCreature = { name: string; key: string; spec: unknown; bbmodelSha256: string; /** Model Studio paint compiled into the skin (./paint.ts) */ paint?: unknown };
export type CreatureDeliverDeps = { managed: ManagedDeps; fs: GuestFs; env?: Record<string, string | undefined>; base?: string; configTemplate?: () => string };
export type CreatureDeliverResult =
  | { ok: true; action: "switched_off" | "no_creatures" | "delivered" | "removed"; wrote: string[]; removed: string[]; restartRequired: boolean; bettermodel?: string; notes: string[] }
  | { ok: false; error: string };

export const creaturesSwitchedOn = (env: Record<string, string | undefined>) => env[MANAGED_REAL_FLAG] === "1" && env[CREATURES_FLAG] === "1";
/** The managed config of the BetterModel pinned for this version's family (catalog managedConfig; the 26 family's file by default). */
export function managedConfigTemplate(mcVersion?: string): string {
  const pin = mcVersion ? pinFor(loadCatalog(), BETTERMODEL_KEY, mcVersion) : null;
  const file = pin && pin.ok && pin.entry.managedConfig ? pin.entry.managedConfig.template : "bettermodel-config.yml";
  return readFileSync(path.join(__dirname, "../managed", path.basename(file)), "utf8");
}
const dependentFor = (projectId: string) => `project:${projectId}`;

/** Re-compile stored creatures and prove the bytes equal what the build recorded (shared with lib/cyrus/delivery). */
export function compileStoredCreatures(namespace: string, creatures: StoredCreature[]): { ok: true; files: { rel: string; data: Buffer }[] } | { ok: false; error: string } {
  const files: { rel: string; data: Buffer }[] = [];
  for (const c of creatures) {
    const chk = checkRigSpec(c.spec, { namespace });
    if (!chk.ok) return { ok: false, error: `creature ${c.name}: ${chk.error}` };
    let paint: ((b: import("../textures/render").Raster) => import("../textures/render").Raster) | undefined;
    if (c.paint !== undefined) {
      const size = (c.paint as { tex?: { w?: number } } | null)?.tex?.w ?? 0;
      const pc = checkCreaturePaint(c.paint, size);
      if (!pc.ok) return { ok: false, error: `creature ${c.name}: ${pc.reason}` };
      paint = paintSkin(c.paint as CreaturePaint);
    }
    const r = compileCreature(chk.spec, namespace, { paint });
    if (!r.ok) return { ok: false, error: `creature ${c.name}: ${r.error}` };
    if (r.creature.bbmodelSha256 !== c.bbmodelSha256 || r.creature.key !== modelKey(namespace, chk.spec.name)) return { ok: false, error: `creature ${c.name}: the model no longer compiles to the recorded bytes (compiler changed?); rebuild the mod` };
    files.push({ rel: `${MODELS_DIR}/${r.creature.key}.bbmodel`, data: Buffer.from(r.creature.bbmodel) });
  }
  return { ok: true, files };
}

export async function deliverCreatures(a: { serverId: string; mcVersion: string; namespace: string; projectId: string; creatures: StoredCreature[] }, deps: CreatureDeliverDeps): Promise<CreatureDeliverResult> {
  const env = deps.env ?? process.env;
  if (!creaturesSwitchedOn(env)) return { ok: true, action: "switched_off", wrote: [], removed: [], restartRequired: false, notes: [`animated creature delivery is switched off (${MANAGED_REAL_FLAG} and ${CREATURES_FLAG} must both be 1)`] };
  const base = deps.base ?? MC_BASE;
  // compile first: nothing touches the server unless every model re-compiles to the recorded bytes
  const compiled = compileStoredCreatures(a.namespace, a.creatures);
  if (!compiled.ok) return compiled;
  const files = compiled.files;
  const notes: string[] = [];
  let bettermodel: string | undefined;
  let restartRequired = false;
  if (files.length) {
    const ens = await ensureManagedPlugin(deps.managed, { serverId: a.serverId, key: BETTERMODEL_KEY, mcVersion: a.mcVersion, dependent: dependentFor(a.projectId) });
    if (!ens.ok) return { ok: false, error: `BetterModel: ${ens.error}` };
    bettermodel = ens.action;
    if (ens.action === "installed" || ens.action === "upgraded") { restartRequired = true; notes.push("the Nxeon-managed BetterModel plugin was installed; it starts with the next server restart"); }
  }
  const wrote: string[] = [];
  // managed config: only when absent or still ours (an owner who edited it keeps their file)
  const cfgPath = `${base}/${CONFIG_PATH}`;
  if (files.length) {
    const cur = await deps.fs.readFile(cfgPath, 256 * 1024);
    const want = Buffer.from(deps.configTemplate ? deps.configTemplate() : managedConfigTemplate(a.mcVersion));
    if (!cur || (cur.toString("utf8").startsWith(CONFIG_MARKER) && !cur.equals(want))) {
      await deps.fs.mkdirp(path.posix.dirname(cfgPath));
      await deps.fs.writeFile(cfgPath, want);
      wrote.push(CONFIG_PATH); restartRequired = true;
    } else if (!cur.toString("utf8").startsWith(CONFIG_MARKER)) notes.push("BetterModel's config.yml was changed by the server owner, so Nxeon left it as it is");
  }
  await deps.fs.mkdirp(`${base}/${MODELS_DIR}`);
  for (const f of files) {
    const cur = await deps.fs.readFile(`${base}/${f.rel}`, 4 * 1024 * 1024);
    if (cur && cur.equals(f.data)) continue;
    const tmp = `${base}/${f.rel}.nx-part`;
    await deps.fs.writeFile(tmp, f.data);
    await deps.fs.rename(tmp, `${base}/${f.rel}`);
    wrote.push(f.rel); restartRequired = true;
  }
  // this project's models the new version no longer has (only files with OUR namespace prefix; others untouched)
  const keep = new Set(files.map((f) => path.posix.basename(f.rel)));
  const removed: string[] = [];
  for (const name of await deps.fs.list(`${base}/${MODELS_DIR}`).catch(() => [] as string[])) {
    if (!name.startsWith(`${a.namespace}_`) || !name.endsWith(".bbmodel") || keep.has(name)) continue;
    await deps.fs.remove(`${base}/${MODELS_DIR}/${name}`);
    removed.push(`${MODELS_DIR}/${name}`); restartRequired = true;
  }
  if (!files.length) {
    const rel = await releaseManagedPlugin(deps.managed, { serverId: a.serverId, key: BETTERMODEL_KEY, dependent: dependentFor(a.projectId) });
    if (!rel.ok) return { ok: false, error: `BetterModel: ${rel.error}` };
    return { ok: true, action: removed.length ? "removed" : "no_creatures", wrote, removed, restartRequired, bettermodel: rel.action, notes };
  }
  if (restartRequired) notes.push("restart the server (or run /bettermodel reload) so BetterModel loads the creatures and rebuilds its resource pack");
  return { ok: true, action: "delivered", wrote, removed, restartRequired, bettermodel, notes };
}

/** The mod left the server: remove its models and release BetterModel (removed when nothing else needs it). */
export async function removeCreatures(a: { serverId: string; mcVersion: string; namespace: string; projectId: string }, deps: CreatureDeliverDeps): Promise<CreatureDeliverResult> {
  return deliverCreatures({ ...a, creatures: [] }, deps);
}

