    child.stdout.on("data", (d) => (stdout += d));
    child.stderr.on("data", (d) => (stderr += d));
    const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
    child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
    child.stdin.on("error", () => {});
    child.stdin.end(opts.input ?? undefined);
  }),
};

async function fly(spec: TestFlightSpec, label: string): Promise<RunResult> {
  for (let attempt = 1, wait = 15000; attempt <= 12; attempt++, wait = Math.min(wait * 2, 120000)) {
    const r = await runTestFlight(spec, { remote: localRemote });
    if (r.report.status !== "busy") return r;
    console.log(`${label}: node-2 busy (another flight), retry ${attempt} in ${wait / 1000}s`);
    await sleep(wait);

  return false;
}

const isBM = (n: string) => n.toLowerCase() === ENGINE_NAME.toLowerCase();

/** Does this build need BetterModel in its flight? Returns the reason, or null. */
export function engineNeed(jar: Buffer | null, creatures: { length: number } | null | undefined): string | null {
  const deps = jar ? jarDependencies(jar) : null;
  if (deps?.depend.some(isBM)) return "the mod's plugin.yml declares depend: BetterModel";
  if (deps?.softdepend.some(isBM)) return "the mod's plugin.yml declares softdepend: BetterModel";
  if (creatures && creatures.length > 0) return "the build ships animated creatures (bettermodel/*.bbmodel)";
  if (jar && jarUsesBetterModel(jar)) return "the mod's code uses BetterModel classes";
  return null;
}

export type EngineDeps = { env?: Record<string, string | undefined>; readJar?: typeof readManagedArtifact; readLedger?: (file: string) => string };

/** Resolve BetterModel for one flight, or null when the build does not need it. Never downloads. */
export async function provisionEngine(a: { jar: Buffer | null; mcVersion: string; namespace?: string | null; creatures?: StoredCreature[] | null }, deps: EngineDeps = {}): Promise<EngineProvision | null> {
  const reason = engineNeed(a.jar, a.creatures ?? null);
  if (!reason) return null;
  const env = deps.env ?? process.env;
  const deps0 = a.jar ? jarDependencies(a.jar) : null;
  const declared = !!deps0 && [...deps0.depend, ...deps0.softdepend].some(isBM);
  const out: EngineProvision = { name: ENGINE_NAME, reason, notes: [], ...(a.jar && !declared && jarUsesBetterModel(a.jar) ? { undeclared: true } : {}) };
  if (out.undeclared) out.notes.push("the mod's plugin.yml does not declare depend: [BetterModel] although its code uses BetterModel");
  const pin = pinFor(loadCatalog(), BETTERMODEL_KEY, a.mcVersion);
  if (!pin.ok) return { ...out, unavailable: pin.error };
  const entry = pin.entry;
  out.version = entry.version;
  try {
    const bytes = await (deps.readJar ?? readManagedArtifact)(entry, env.CYRUS_MANAGED_PLUGIN_DIR || "");
    out.jar = { bytes, sha256: createHash("sha256").update(bytes).digest("hex") };
  } catch (e) {
    return { ...out, unavailable: `BetterModel ${entry.version} jar is not available on this host (${(e as Error).message.slice(0, 160)})` };
  }
  // runtime libraries are seeded from node-2 (the flight has no internet): names come from the pinned ledger
  if (entry.runtimeLibraries) {
    try {
      const raw = deps.readLedger ? deps.readLedger(entry.runtimeLibraries) : readFileSync(path.join(__dirname, "../managed", path.basename(entry.runtimeLibraries)), "utf8");
      const led = JSON.parse(raw) as { paperLibraries?: { seed?: string; target?: string }; libby?: { seed?: string; target?: string } };
      out.seeds = [led.paperLibraries, led.libby].filter((s): s is { seed: string; target: string } => !!s?.seed && !!s?.target).map((s) => ({ from: s.seed, to: s.target }));
    } catch (e) {
      return { ...out, unavailable: `BetterModel ${entry.version} runtime library ledger is unreadable (${(e as Error).message.slice(0, 120)})` };
    }
  }
  const files: ServerFile[] = [];
  const cfg = entry.managedConfig;
  if (cfg) {
    const text = managedConfigTemplate(a.mcVersion);
    if (Buffer.byteLength(text) <= MAX_SERVER_FILE_BYTES) files.push({ path: cfg.path, content: text });
  }
  // the build's own models (re-compiled and byte-checked like the delivery does); what does not fit a flight file is
  // reported, never silently dropped. Model load problems inside BetterModel are warnings, not mod failures.
  if (a.creatures?.length && a.namespace) {
    const c = compileStoredCreatures(a.namespace, a.creatures);
    if (!c.ok) out.notes.push(`BetterModel models were not placed in the flight: ${c.error}`.slice(0, 280));
    else {
      let placed = 0, skipped = 0;
      for (const f of c.files) {
        if (files.length < MAX_SERVER_FILES && f.data.length <= MAX_SERVER_FILE_BYTES) { files.push({ path: f.rel, content: f.data.toString("utf8") }); placed++; } else skipped++;
      }
      out.notes.push(`BetterModel models placed in the flight: ${placed}${skipped ? `, ${skipped} left out (over the ${MAX_SERVER_FILE_BYTES / 1024} KB flight file limit)` : ""}`);
    }
  }
  if (files.length) out.files = files;
  return out;
}
