// Cyrus engine core: the plan-tier gate for custom assets (MASTER-PLAN section 2, owner decisions).
//   free, katara -> no asset studios, no asset generation
//   saka         -> SOUND (Sound Studio + Sound Library)
//   all          -> SOUND + TEXTURE (the top plan; it includes the Yakko model)
// Tiers are cumulative. The gate applies only to CREATING or EDITING asset content (a studio, a library pick, an
// upload, or Cyrus generating it automatically inside a build). Keeping, installing, rebuilding unchanged,
// exporting, importing your own mod and composing Mod Packs are NEVER gated. An unknown plan or token state
// denies creation (fail closed) but never denies keep/install/export.
// Pure + client-safe; the server must call it again on every request (the UI check is only a hint).
import type { AssetKind, AssetSource, ModSpec } from "./spec";
import { ASSET_KINDS } from "./spec";

export const ASSET_PLANS = ["free", "katara", "saka", "all"] as const;
export type AssetPlan = (typeof ASSET_PLANS)[number];
const RANK: Record<AssetPlan, number> = { free: 0, katara: 1, saka: 2, all: 3 };
export const PLAN_LABEL: Record<AssetPlan, string> = { free: "Free", katara: "Katara", saka: "Saka", all: "All models" };

/**
 * THE one place that reconciles plan spellings. The token economy calls the top plan `all`
 * (lib/cyrus/tokens/config.ts TOKEN_TIERS); the UI and the model list call it after its top model, Yakko.
 * Anything else (null, a typo, a future plan) is unknown -> null, and callers fail closed.
 */
export function normalizePlan(raw: unknown): AssetPlan | null {
  if (typeof raw !== "string") return null;
  const v = raw.trim().toLowerCase();
  if (v === "all" || v === "yakko" || v === "all models") return "all";
  if (v === "free" || v === "katara" || v === "saka") return v;
  return null;
}

/** Plan from a token state (lib/cyrus/tokens/view.ts TokenState) or anything with a `tier`. Missing state -> null (unknown). */
export const planFromTokenState = (state: { tier?: unknown } | null | undefined): AssetPlan | null => normalizePlan(state?.tier);

/**
 * Cheapest plan that may create/edit each kind. `model` and `ui` are visual assets drawn with the texture tools,
 * so they follow the Texture Studio (top plan).
 */
export const ASSET_MIN_PLAN: Readonly<Record<AssetKind, AssetPlan>> = { sound: "saka", texture: "all", model: "all", ui: "all" };

export const ASSET_OPS = ["create", "edit", "keep", "install", "export", "rebuild", "import", "compose"] as const;
export type AssetOp = (typeof ASSET_OPS)[number];
export const GATED_OPS: readonly AssetOp[] = ["create", "edit"];

export type AssetDecision =
  | { ok: true }
  | { ok: false; code: "asset_locked" | "plan_unknown" | "bad_request"; reason: string; needs?: AssetPlan };

const KIND_WORD: Record<AssetKind, string> = { sound: "custom sounds", texture: "custom textures", model: "custom models", ui: "custom menu and HUD art" };

export function canAsset(plan: unknown, kind: AssetKind, op: AssetOp): AssetDecision {
  if (!(ASSET_OPS as readonly string[]).includes(op)) return { ok: false, code: "bad_request", reason: `unknown asset operation ${String(op)}` };
  if (!GATED_OPS.includes(op)) return { ok: true }; // keep / install / export / rebuild / import / compose: never gated
  if (!(ASSET_KINDS as readonly string[]).includes(kind)) return { ok: false, code: "bad_request", reason: `unknown asset kind ${String(kind)}` };
  const needs = ASSET_MIN_PLAN[kind];
  const p = normalizePlan(plan);
  if (!p) return { ok: false, code: "plan_unknown", needs, reason: `We couldn't confirm your Cyrus plan, so ${KIND_WORD[kind]} can't be created or edited right now.` };
  if (RANK[p] < RANK[needs]) return { ok: false, code: "asset_locked", needs, reason: `Creating or editing ${KIND_WORD[kind]} needs the ${PLAN_LABEL[needs]} plan or higher.` };
  return { ok: true };
}

/**
 * Model Studio (Cyrus Layer 1 viewport + paint; owner decision 2026-10-10): it sits in the top plan with the Texture
 * Studio and Texture Library, through the SAME gate (kind "model", ASSET_MIN_PLAN.model = "all"). Every studio action
 * maps to an asset op: looking at a model (open, orbit, channel views, in-game contexts, the server preview render),
 * installing and exporting are never gated; every action that CREATES or CHANGES model content (paint, fill, decal,
 * layers, drafts, saving a revision, asking Cyrus for a model edit) is "edit" and needs the top plan. An unknown plan
 * fails closed for those and never for viewing. Unknown actions are refused (bad_request), never allowed.
 */
export const MODEL_STUDIO_ACTIONS = ["view", "orbit", "preview", "install", "export", "paint", "fill", "decal", "layer", "draft", "save", "ai_edit", "transform", "material", "rebuild"] as const;
export type ModelStudioAction = (typeof MODEL_STUDIO_ACTIONS)[number];
export const MODEL_STUDIO_OP: Readonly<Record<ModelStudioAction, AssetOp>> = {
  view: "keep", orbit: "keep", preview: "keep", install: "install", export: "export",
  paint: "edit", fill: "edit", decal: "edit", layer: "edit", draft: "edit", save: "edit", ai_edit: "edit",
  // layer 3 (retexture + light edit of glTF meshes): moving a part, changing a material, rebuilding a template mesh
  transform: "edit", material: "edit", rebuild: "edit",
};
export function canModelStudio(plan: unknown, action: ModelStudioAction): AssetDecision {
  if (!(MODEL_STUDIO_ACTIONS as readonly string[]).includes(action)) return { ok: false, code: "bad_request", reason: `unknown Model Studio action ${String(action)}` };
  return canAsset(plan, "model", MODEL_STUDIO_OP[action]);
}

/** What a spec asset slot asks the engine to do with asset content. */
export function assetOpForSource(source: AssetSource): AssetOp {
  switch (source) {
    case "generate": case "library": case "upload": return "create";
    case "edit": return "edit";
